namespace sv_2d89bd4cb0c148a9bee810eed7c58666.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service (one per circuit) that holds theme state and notifies subscribers on change.
/// </summary>
public sealed class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Fired whenever Theme or AccentColor changes.
    /// </summary>
    public event Action? OnChange;

    /// <summary>
    /// Batch-update both values with a single notification.
    /// </summary>
    public void SetPreferences(ThemeMode theme, string accentColor)
    {
        bool changed = _theme != theme || _accentColor != accentColor;
        _theme = theme;
        _accentColor = accentColor;
        if (changed) NotifyChanged();
    }

    private void NotifyChanged() => OnChange?.Invoke();
}

@* 
    Interactive component placed in the static layout.
    It subscribes to ThemeService and pushes changes to the DOM via JS interop.
    Because it's marked @rendermode InteractiveServer, it stays alive across
    enhanced navigations within the same circuit.
*@
@rendermode InteractiveServer
@inject ThemeService ThemeService
@inject IJSRuntime JS
@implements IDisposable

<span id="theme-indicator" class="badge rounded-pill @BadgeClass">
    @ThemeService.Theme
</span>

@code {
    private string BadgeClass => ThemeService.Theme switch
    {
        ThemeMode.Dark => "text-bg-dark",
        ThemeMode.Light => "text-bg-light text-dark border",
        _ => "text-bg-secondary"
    };

    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await ApplyThemeToDOM();
        }
    }

    private async void HandleThemeChanged()
    {
        await InvokeAsync(async () =>
        {
            StateHasChanged();
            await ApplyThemeToDOM();
        });
    }

    private async Task ApplyThemeToDOM()
    {
        try
        {
            await JS.InvokeVoidAsync("applyTheme",
                ThemeService.Theme.ToString().ToLowerInvariant(),
                ThemeService.AccentColor);
        }
        catch (JSDisconnectedException) { }
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

// Applies theme mode and accent color to the document root.
// Called from ThemeProvider via JS interop.
window.applyTheme = function (mode, accentColor) {
    const html = document.documentElement;

    // Resolve "system" to actual preference
    let resolved = mode;
    if (mode === "system") {
        resolved = window.matchMedia("(prefers-color-scheme: dark)").matches
            ? "dark"
            : "light";
    }

    html.setAttribute("data-bs-theme", resolved);
    html.style.setProperty("--app-accent-color", accentColor);
};

@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 500px;">
    <div class="mb-3">
        <label class="form-label fw-bold">Theme Mode</label>
        <div class="btn-group d-flex" role="group">
            @foreach (var mode in Enum.GetValues<ThemeMode>())
            {
                <button type="button"
                        class="btn @(mode == _selectedTheme ? "btn-primary" : "btn-outline-primary")"
                        @onclick="() => SelectTheme(mode)">
                    @mode
                </button>
            }
        </div>
    </div>

    <div class="mb-3">
        <label class="form-label fw-bold" for="accent-color">Accent Color</label>
        <input id="accent-color" type="color" class="form-control form-control-color"
               value="@_selectedAccent" @onchange="AccentChanged" />
    </div>

    <button class="btn btn-success" @onclick="Save">Save Preferences</button>

    @if (_saved)
    {
        <div class="alert alert-success mt-3 mb-0">Preferences saved!</div>
    }
</div>

@code {
    private ThemeMode _selectedTheme;
    private string _selectedAccent = "#0d6efd";
    private bool _saved;

    protected override void OnInitialized()
    {
        _selectedTheme = ThemeService.Theme;
        _selectedAccent = ThemeService.AccentColor;
        ThemeService.OnChange += HandleExternalChange;
    }

    private void SelectTheme(ThemeMode mode)
    {
        _selectedTheme = mode;
        _saved = false;
    }

    private void AccentChanged(ChangeEventArgs e)
    {
        _selectedAccent = e.Value?.ToString() ?? _selectedAccent;
        _saved = false;
    }

    private void Save()
    {
        // This updates the service and fires OnChange, which triggers
        // ThemeProvider (and any other subscriber) to update immediately.
        ThemeService.SetPreferences(_selectedTheme, _selectedAccent);
        _saved = true;
    }

    private void HandleExternalChange()
    {
        InvokeAsync(() =>
        {
            _selectedTheme = ThemeService.Theme;
            _selectedAccent = ThemeService.AccentColor;
            StateHasChanged();
        });
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleExternalChange;
    }
}

