// Applies theme mode and accent color to the document root.
// Called from ThemeProvider via JS interop.
window.applyTheme = function (mode, accentColor) {
    const html = document.documentElement;

    // Resolve "system" to actual preference
    let resolved = mode;
    if (mode === "system") {
        resolved = window.matchMedia("(prefers-color-scheme: dark)").matches
            ? "dark"
            : "light";
    }

    html.setAttribute("data-bs-theme", resolved);
    html.style.setProperty("--app-accent-color", accentColor);
};

